var createHeader = function()
{
  var txt = 'Export MOH';
  return txt;
};

var getData = function(daten)
{
  this.prozesstreue=daten.progressBar.value;
  this.kapitel=daten.cbDiagnosis.currentText+' A'+(daten.tabWidget.currentIndex-daten.kapitelstart+1);
  this.tagesdatum=dateToString(daten.deTagesdatum.date);
  this.verantwarzt=daten.leVerantwArzt.text;
  this.mego=daten.leMEGO.text;
  this.patientenid=daten.lePatientenID.text;
};

Model.prototype.pbExportClicked = function()
{
  if(this.tabWidget.currentIndex === 0)
  {
    var fo = new STC_FORMOBJECT();
    fo.setHeader( createHeader() );
    var data = new getData(this);
    fo.setScriptValue( data );
    var source = 'Export';
    var appl   = 'Medical Operation Handbook';
    var free1  = this.cbDiagnosis.currentText+' A'+(this.tabWidget.currentIndex-kapitelstart+1);
    var free2  = '';
    var free3  = '';
    var free4  = '';
    var note1  = '';
    var note2  = '';
    var note3  = '';
    this.objectList.createObject( source, appl, free1, free2, free3, free4, note1, note2, note3, fo );
    var idx = this.objectList.currentIndex();
    this.objectList.copyObjectTo( this.objectList.objectFileName[idx], 'moh-export.xml' );
    //const xls = new xlsExport(exportxls, this.cbDiagnosis.currentText);
    //xls.exportToXLS('export.xls');
  }
}

