Model.prototype.lwChapterDoubleClicked = function()
{
  dirpath="";
  var index=0;
  var selectedString=this.wrapperLwChapter.selectedItems();
  var listChapter = ST_SETTINGS.getValue("MOHDB.txt", dirpath+"/Chapter", "").split("_");
  var index = 0;
  for(var x=0;x<dirpatharray.length;x++)
  {
    dirpath = this.wrapperLwChapter.getItemText(x);
    if(this.wrapperLwChapter.getItemText(x) != selectedString)
    {
      index++;
    }
    else
    {
      break;
    }
  }
  this.lwChapter.clear();
  dirpatharray.slice(index+1, dirpatharray.length-index-1);
  this.wrapperLwChapter.insertItem(0, null);
  for(var y=0;y<index;y++)
  {
      this.wrapperLwChapter.insertItem(x, dirpatharray[y]);
  }
  this.twChapter.clearContents();
  this.twElemente.clearContents();
  this.wrapperTWElemente.setRowCount(0);
  this.twAuswahl.clearContents();
  this.wrapperTWAuswahl.setRowCount(0);
}

Model.prototype.twChapterDoubleClicked = function()
{
  var index = this.wrapperTwChapter.currentRow();  
  var elemente = ST_SETTINGS.getValue("MOHDB.txt", dirpath+"/"+this.wrapperTwChapter.item(index,0), "").split("_");
  if(elemente[1] === "Folder")
  {
    if(elemente[0] === dirpath) 
    {
      dirpath = "";
      dirpatharray = [];
    }
    dirpath = elemente[0];
    dirpatharray.push(elemente[0]);
    this.wrapperLwChapter.insertItem(dirpatharray.length, elemente[0]);
    this.wrapperTWElemente.setRowCount(0);
    this.wrapperTWAuswahl.setRowCount(0);
    this.twChapter.clearContents();
  }
}

Model.prototype.twChapterSelectionChanged = function(row, column)
{
  rowChapter = row;
  this.twElemente.clearContents();
  this.twElemente.toolTip = null;
  var elemente = ST_SETTINGS.getValue("MOHDB.txt", dirpath+this.wrapperTwChapter.item(rowChapter,0)+"/Elements", "").split("_");
  var elementecount = elemente.length;
  if(ST_SETTINGS.getValue("MOHDB.txt", dirpath+this.wrapperTwChapter.item(rowChapter,0)+"/Elements", "") === "")
  {
    elementecount = 0;
    this.wrapperTWAuswahl.setRowCount(0);
  }
  this.wrapperTWElemente.setLineEditColumns( this, null );
  this.wrapperTWElemente.setRowCount(elementecount);
  for(var elementindex = 0; elementindex<elementecount; elementindex++)
  {
    var eigenschaften = ST_SETTINGS.getValue("MOHDB.txt", dirpath+this.wrapperTwChapter.item(rowChapter,0)+"/"+elemente[elementindex], "").split("_");
    var listChapter = ST_SETTINGS.getValue("MOHDB.txt", dirpath+"/Chapter", "").split("_");
    var listChapterItems = ST_SETTINGS.getValue("MOHDB.txt", dirpath+"/"+listChapter[rowChapter], "").split("_");
    if(listChapterItems[1] === "Chapter")
    {
      for(var x=0;x<eigenschaften.length;x++)
      {
        this.wrapperTWElemente.setItemData(elementindex, x, eigenschaften[x], false);
      }
    }
    if(listChapterItems[1] === "Folder")
    {
      this.wrapperTWElemente.setRowCount(0);
      this.wrapperTWAuswahl.setRowCount(0);
    }
    listarray = [];
    this.lwRegelT1.clear();
  }
}

Model.prototype.twElementeSelectionChanged = function(row, column)
{
  rowElements = row;
  this.twAuswahl.clearContents();
  this.twAuswahl.toolTip = null;
  var listChapter = ST_SETTINGS.getValue("MOHDB.txt", dirpath+"/Chapter", "").split("_");
  var elemente = ST_SETTINGS.getValue("MOHDB.txt", dirpath+this.wrapperTwChapter.item(this.wrapperTwChapter.currentRow(),0)+"/Elements", "").split("_");
  var eigenschaften = ST_SETTINGS.getValue("MOHDB.txt", dirpath+this.wrapperTwChapter.item(this.wrapperTwChapter.currentRow(),0)+"/"+elemente[rowElements], "").split("_");
  var auswahl = ST_SETTINGS.getValue("MOHDB.txt", dirpath+this.wrapperTwChapter.item(this.wrapperTwChapter.currentRow(),0)+elemente[rowElements]+"/Selection", "").split("_");
  var auswahlcount = auswahl.length;
  this.wrapperTWAuswahl.setLineEditColumns( this, "lineVisiteValidate" );
  this.wrapperTWAuswahl.setRowCount(auswahlcount);
  
  for(var auswahlindex = 0; auswahlindex<auswahlcount; auswahlindex++)
  {
    var auswahlwerte = ST_SETTINGS.getValue("MOHDB.txt", dirpath+this.wrapperTwChapter.item(this.wrapperTwChapter.currentRow(),0)+elemente[rowElements]+"/"+auswahl[auswahlindex], "").split("_");
    for(var x=0;x<auswahlwerte.length;x++)
    {
      this.wrapperTWAuswahl.setItemData(auswahlindex, x, auswahlwerte[x], eigenschaften[2] === "Text");
      if(eigenschaften[2] === "Mixed" && x === auswahlindex)
      {
        this.wrapperTWAuswahl.setItemData(auswahlindex, 1, this.objSelectionText[listChapter[rowChapter]+elemente[rowElements]+auswahl[auswahlindex]], auswahlwerte[7]);
      }
    }
    if(elemente[row] === "TR" && score >= auswahlwerte[2])
    {
      this.wrapperTWAuswahl.setCurrentCell(auswahlindex,0);
      this.twAuswahl.toolTip = this.wrapperTWAuswahl.item(auswahlindex,0)+"\n"+this.wrapperTWAuswahl.item(auswahlindex,1);
    }
    if(eigenschaften[2] === "Text")
    {
      this.wrapperTWAuswahl.setItemData(0, 1, this.objSelectionText[listChapter[rowChapter]+elemente[rowElements]+auswahl[auswahlindex]], true);
    }
  } 
  for(var indexAuswahl=0;indexAuswahl<auswahl.length;indexAuswahl++)
  {
    if(auswahl[indexAuswahl] === this.objSelection[listChapter[rowChapter]+elemente[rowElements]])
    {
      this.wrapperTWAuswahl.setCurrentCell(indexAuswahl,0);
    }
  }
  var temparray = [];
  if(typeof listarray === "undefined") listarray = [];
  for(var index = 0;index<listarray.length;index++)
  {
    insertInListWithoutDuplicates(listarray[index], temparray, this.lwRegelT1, this.wrapperLwRegelT1);
  }
  this.twElemente.toolTip = eigenschaften.slice(0,2).join('\n');
}

Model.prototype.twAuswahlSelectionChanged = function(row, column)
{
  var listChapter = ST_SETTINGS.getValue("MOHDB.txt", dirpath+"/Chapter", "").split("_");
  var elemente = ST_SETTINGS.getValue("MOHDB.txt", dirpath+this.wrapperTwChapter.item(this.wrapperTwChapter.currentRow(),0)+"/Elements", "").split("_");
  var eigenschaften = ST_SETTINGS.getValue("MOHDB.txt", dirpath+this.wrapperTwChapter.item(this.wrapperTwChapter.currentRow(),0)+"/"+elemente[rowElements], "").split("_");
  rowAuswahl = row;
  var auswahl = ST_SETTINGS.getValue("MOHDB.txt", dirpath+this.wrapperTwChapter.item(this.wrapperTwChapter.currentRow(),0)+elemente[rowElements]+"/Selection", "").split("_");
  var auswahlwerte = ST_SETTINGS.getValue("MOHDB.txt", dirpath+this.wrapperTwChapter.item(this.wrapperTwChapter.currentRow(),0)+elemente[rowElements]+"/"+auswahl[rowAuswahl], "").split("_");
  if(auswahlwerte[6] !== "" && typeof auswahlwerte[6] != "undefined") print(auswahlwerte[6]);
  if(eigenschaften[2] === "Text" && (column !== 1 || column === null))
  {
    this.wrapperTWAuswahl.setItemData(row, column, this.wrapperTWAuswahl.item(row, column), false);
  }

  this.twAuswahl.toolTip = this.wrapperTWAuswahl.item(rowAuswahl,0)+"\n"+this.wrapperTWAuswahl.item(rowAuswahl,1);
  if(typeof listarray === "undefined") listarray = [];
  insertInListWithoutDuplicates(auswahlwerte[5], listarray, this.lwRegelT1, this.wrapperLwRegelT1);
  this.objSelection[listChapter[rowChapter]+elemente[rowElements]] = auswahl[rowAuswahl];
}

