Model.prototype.twFMM47Validate = function(row, column, text)
{
  if(column === 2 || column === 3 || column === 4)
  {
    return true;
  }
}

Model.prototype.wrapperTWFMM47CellClicked = function(row, column)
{
  this.twFMM47.toolTip = this.wrapperTWFMM47.item(row, column);
}

Model.prototype.wrapperTWFMM47ItemChanged = function(row, column, index)
{
  if(column === 2 && arrFMMMoeglichIndex[row] != index)
  {
    arrFMMMoeglich[row] = "trifft zu";
    arrFMMGeschwaechtMoeglich[row] = "trifft nicht zu";
    arrFMMNichtMoeglich[row] = "trifft nicht zu";
    arrFMMMoeglichIndex[row] = 1;
    arrFMMGeschwaechtMoeglichIndex[row] = 2;
    arrFMMNichtMoeglichIndex[row] = 2;
    this.wrapperTWFMM47.setItemData(row, 2, arrFMMMoeglich[row], true);
    this.wrapperTWFMM47.setItemData(row, 3, arrFMMGeschwaechtMoeglich[row], true);
    this.wrapperTWFMM47.setItemData(row, 4, arrFMMNichtMoeglich[row], true);
    return true;
  }
  
  if(column === 3 && arrFMMGeschwaechtMoeglichIndex[row] != index)
  {
    arrFMMMoeglich[row] = "trifft nicht zu";
    arrFMMGeschwaechtMoeglich[row] = "trifft zu";
    arrFMMNichtMoeglich[row] = "trifft nicht zu";
    arrFMMMoeglichIndex[row] = 2;
    arrFMMGeschwaechtMoeglichIndex[row] = 1;
    arrFMMNichtMoeglichIndex[row] = 2;
    this.wrapperTWFMM47.setItemData(row, 2, arrFMMMoeglich[row], true);
    this.wrapperTWFMM47.setItemData(row, 3, arrFMMGeschwaechtMoeglich[row], true);
    this.wrapperTWFMM47.setItemData(row, 4, arrFMMNichtMoeglich[row], true);
    return true;
  }
  if(column === 4 && arrFMMNichtMoeglichIndex[row] != index)
  {
    arrFMMMoeglich[row] = "trifft nicht zu";
    arrFMMGeschwaechtMoeglich[row] = "trifft nicht zu";
    arrFMMNichtMoeglich[row] = "trifft zu";
    arrFMMMoeglichIndex[row] = 2;
    arrFMMGeschwaechtMoeglichIndex[row] = 2;
    arrFMMNichtMoeglichIndex[row] = 1;
    this.wrapperTWFMM47.setItemData(row, 2, arrFMMMoeglich[row], true);
    this.wrapperTWFMM47.setItemData(row, 3, arrFMMGeschwaechtMoeglich[row], true);
    this.wrapperTWFMM47.setItemData(row, 4, arrFMMNichtMoeglich[row], true);
    return true;
  }
}
