function initEPList(context, text)
{
  context.lwEPRed53.clear();
  context.lwEPYellow53.clear();
  context.lwEPGreen53.clear();
  for(var index = 0; index < arrEPRed.length; index++)
  {
    if(text === "" || arrEPRed[index].split(text).length > 1)
    {
      context.wrapperLWEPRed53.insertItem(index+1, arrEPRed[index]);
    }
  }
  for(var index = 0; index < arrEPYellow.length; index++)
  {
    if(text === "" || arrEPYellow[index].split(text).length > 1)
    {
      context.wrapperLWEPYellow53.insertItem(index+1, arrEPYellow[index]);
    }
  }
  for(var index = 0; index < arrEPGreen.length; index++)
  {
    if(text === "" || arrEPGreen[index].split(text).length > 1)
    {
      context.wrapperLWEPGreen53.insertItem(index+1, arrEPGreen[index]);
    }
  }
}

