Model.prototype.pbSaveClicked = function()
{
  if(this.leVerantwArzt.text.trim() != "")
  {
    this.ui.accept();
  }
  else
  {
    this.lblVerantwArzt.styleSheet = "background-color:red;color:white;";
    print("Bitte geben Sie ein Arztkürzel ein !");
    this.leVerantwArzt.setFocus();
    this.tbtoolBox.currentIndex = 0;
  }
}

Model.prototype.pbCancelClicked = function()
{
  this.ui.reject();  
}

