String.prototype.replaceAll = function(search, replacement) {
    var target = this;
    return target.split(search).join(replacement);
};

String.prototype.replaceAllNotHTML = function() {
    var target = this;
    target = target.replaceAll('\n', '<br/>');
    target = target.replaceAll('< ', '&lt; ');
    target = target.replaceAll('> ', '&gt; ');
    return target;
};

String.prototype.replaceAllUmlaute = function() {
  var target = this;
  target = target.replaceAll('ä', '.ae.');
  target = target.replaceAll('ö', '.oe.');
  target = target.replaceAll('ü', '.ue.');
  target = target.replaceAll('Ä', '.Ae.');
  target = target.replaceAll('Ö', '.Oe.');
  target = target.replaceAll('Ü', '.Ue.');
  target = target.replaceAll('ß', '.ss.');
  target = target.replaceAll('é', '.e/.');
  target = target.replaceAll('è', '.e\\.');
  target = target.replaceAll(/~xe4/g, 'ä');
  target = target.replaceAll(/~xf6/g, 'ö');
  target = target.replaceAll(/~xfc/g, 'ü');
  target = target.replaceAll(/~xc4/g, 'Ä');
  target = target.replaceAll(/~xd6/g, 'Ö');
  target = target.replaceAll(/~xdc/g, 'Ü');
  target = target.replaceAll(/~xdf/g, 'ß');
  target = target.replaceAll(/~x61/g, 'a');
  target = target.replaceAll(/~x62/g, 'b');
  target = target.replaceAll(/~x63/g, 'c');
  target = target.replaceAll(/~x64/g, 'd');
  target = target.replaceAll(/~x65/g, 'e');
  target = target.replaceAll(/~x66/g, 'f');
  target = target.replaceAll(/~x67/g, 'g'); 
  target = target.replaceAll(/~x68/g, 'h');
  target = target.replaceAll(/~x69/g, 'i');
  target = target.replaceAll(/~x6a/g, 'j');
  target = target.replaceAll(/~x6b/g, 'k'); 
  target = target.replaceAll(/~x6c/g, 'l'); 
  target = target.replaceAll(/~x6d/g, 'm'); 
  target = target.replaceAll(/~x6e/g, 'n'); 
  target = target.replaceAll(/~x6f/g, 'o'); 
  target = target.replaceAll(/~x70/g, 'p');
  target = target.replaceAll(/~x71/g, 'q'); 
  target = target.replaceAll(/~x72/g, 's'); 
  target = target.replaceAll(/~x73/g, 'r'); 
  target = target.replaceAll(/~x74/g, 't');
  target = target.replaceAll(/~x75/g, 'u');
  target = target.replaceAll(/~x76/g, 'v');
  target = target.replaceAll(/~x77/g, 'w');
  target = target.replaceAll(/~x78/g, 'x');
  target = target.replaceAll(/~x79/g, 'y'); 
  target = target.replaceAll(/~x7a/g, 'z');

  return target;
}

function printCheckBox( truefalse )
{
  if(truefalse === true)
    return '<span style="font-family: Wingdings 2">&#82;</span>';
  else
    return '<span style="font-family: Wingdings 2">&#163;</span>';
}

function printRadioButton( truefalse )
{
  if(truefalse === true)
    return '<span style="font-family: Wingdings">&#164;</span>';
  else
    return '<span style="font-family: Wingdings">&#161;</span>';
}


Model.prototype.setup = function( currentObjectIndex )
{
  if ( ST_ARGUMENTS.scriptCalledFrom() === 2 ) {
    this.currentObjectIndex = currentObjectIndex;
    if ( this.currentObjectIndex >= 0 ) {
      if ( this.objectList.formIsObjectOwner( this.currentObjectIndex ) ) {
        this.formObject = this.objectList.readObject( this.currentObjectIndex );
      } else {
        this.currentObjectIndex = -1;
      }
    }
  }

  this.formData = this.formObject.getScriptValue();
  this.formData.__proto__ = FormDataScoreFile.prototype;

  /*
  if ( this.formData.version !== 1 ) {
    throw( "Unbekanntes Datenformat '" + this.formData.version + "'" );
  }
  */

  if ( this.currentObjectIndex < 0 ) {
    this.formData.patientenid = this.patient.getMedistarPatNumber();
    this.formData.patvorname = this.patient.getPatientenVorName();
    this.formData.patname = this.patient.getPatientenName(); 
    this.formData.patgebdatum = this.patient.getPatientenGebDatum();
    this.formData.tagesdatum = ST_DATETIME.currentDate( "yyyyMMdd" );
    if(this.formData.tabindex === 13)
    {
      this.formData.pbcstext = "";
      this.formData.pbcsenabled = false;
    }
    else
    {
      this.formData.pbcstext = "Score berechnen";
      this.formData.pbcsenabled = true;
    }

    if(typeof this.formData.tagesdatum === "undefined")
    {
      var filename = ST_OBJECTS.objectFileName(ST_OBJECTS.currentIndex);
      var filearray = filename.split("-");
      this.formData.tagesdatum = ST_DATETIME.currentDate(filearray[3]);
    }
    
    setPressedButtonCalculateScore(this);
  }
  
  this.orgFormData = this.formData.clone();
  this.orgFormData.__proto__ = FormDataScoreFile.prototype;

  this.uiDefaultSetup( this.formData );
}

