function main()
{
  var ui;
  allesgeladen = false;
  try {
    this.objectList = ViewFileList.getObjectList();
    this.patient = ViewFileList.getPatient();
  } catch( exception ) {
    try {
      this.objectList = ViewFileDetail.getObjectList();
      this.patient = ViewFileDetail.getPatient();
    } catch( exception ) {
      try {
        this.objectList = ViewFilePreView.getObjectList();
        this.patient = ViewFilePreView.getPatient();
      } catch( exception ) {
        throw( exception );
      }
    }
  }
  //print(ST_ARGUMENTS.userName().split('/')[0]); //Hostname
  //print(ST_ARGUMENTS.userName().split('/')[1]); //Benutzername
  
  var tabindex = 0;
  if(ST_ARGUMENTS.scriptCalledFrom() === 2)
  {
    tabindex = this.objectList.readObject(this.objectList.currentIndex()).getScriptValue().tabindex;
  }
  g_args = [];
  if(ST_ARGUMENTS.scriptCalledFrom() === 1)
  {
    g_args = ST_ARGUMENTS.args;
    if(g_args.length > 0 && g_args[0].trim() === "standard")
    {
      tabindex = 9;
    }
  }
  if(ST_ARGUMENTS.scriptCalledFrom() === 2)
  {
    if(!this.objectList.isFormObject(this.objectList.currentIndex()))
    {
      print("Bitte ein Formularobjekt auswählen !");
      return;
    }
    /*if(!this.objectList.formIsObjectOwner(this.objectList.currentIndex()))
    {
      print("Dieses Formularobjekt ist kein Medical Operation Handbook !");
      return;
    }*/
    g_args = this.objectList.readObject(this.objectList.currentIndex()).getScriptValue().g_args;
    if(typeof this.objectList.readObject(this.objectList.currentIndex()).getScriptValue().g_args === "undefined")
    {
      g_args = [];
    }
  }
  if(g_args.length > 0 && g_args[0].trim() === "standard")
  {
    if(g_args.length === 2)
    {
      g_args = [];
      g_args[0] = "debug";
    }
    else
    {
      g_args = [];
    }
  }
  if(typeof tabindex === "undefined")
  {
    if(ST_ARGUMENTS.scriptCalledFrom() === 1)
    {
      tabindex = 0;
    }
    if(ST_ARGUMENTS.scriptCalledFrom() === 2)
    {
      tabindex = this.objectList.readObject(this.objectList.currentIndex()).getScriptValue().tabindex;
    }
  }
  if(g_args.length === 0 || (g_args.length > 0 && g_args[0].trim() === "debug"))
  {
	  if(tabindex === 23) 
	  {
		 if(g_args[0] === "debug")
		 {
			g_args[1] = "debug";
		 }	
		 g_args[0] = "parkinson";
	 }	
	 if(tabindex === 43 || tabindex === 13 || tabindex === 30 || tabindex === 31)
	 {
		if(g_args[0] === "debug")
		{
			g_args[1] = "debug";
		}	
    g_args[0] = "postop";
    
    if(tabindex === 13)
    {
      tabindex = 43;
      tabindexPOSTOP = 3;
    }

    if(tabindex === 30)
    {
      tabindex = 43;
      tabindexPOSTOP = 0;
    }

    if(tabindex === 31)
    {
      tabindex = 43;
      tabindexPOSTOP = 2;
    }
   }
   if(tabindex === 45) 
	 {
		if(g_args[0] === "debug")
		{
			g_args[1] = "debug";
		}	
		g_args[0] = "dupm";
	 }
   if(tabindex === 56) 
	 {
		if(g_args[0] === "debug")
		{
			g_args[1] = "debug";
		}	
		g_args[0] = "diagnostik";
	 }	
  }
  if(g_args.length === 0 || (g_args.length > 0 && g_args[0].trim() === "debug") || (g_args.length > 0 && g_args[0].trim() === "standard"))
  {
	ui = ST_GUI.loadUi( "Score.ui" );
  }
  if(g_args.length > 0 && g_args[0].trim() === "parkinson")
  {
	ui = ST_GUI.loadUi( "ScoreParkinson.ui" );
  }
  if(g_args.length > 0 && g_args[0].trim() === "postop")
  {
	ui = ST_GUI.loadUi( "ScorePostOP.ui" );
  }
  if(g_args.length > 0 && g_args[0].trim() === "dupm")
  {
  ui = ST_GUI.loadUi( "ScoreDUPM.ui" );
  }
  if(g_args.length > 0 && g_args[0].trim() === "diagnostik")
  {
  ui = ST_GUI.loadUi( "ScoreDiagnostik.ui" );
  }
  if ( ui !== null ) {
	mohmodel = new Model( ui );
    mohmodel.exec();
  } else {
    throw( "UI-Datei nicht gefunden oder Fehler in UI-Datei." );
  }
}

main();
